mapper.delete:
delete from reference_route_attractions
where reference_route_id = #{referenceRouteId}
  and visit_order = #{visitOrder}

mapper.update:
update reference_route_attractions
set poi_id = #{poiId},
    visit_time = #{visitTime},
    recommended_duration = #{recommendedDuration},
    notes = #{notes}
where reference_route_id = #{referenceRouteId}
  and visit_order = #{visitOrder}

mapper.select:
select 
from reference_route_attractions
where reference_route_id = #{referenceRouteId}
  and visit_order = #{visitOrder}
